const tabs=[{id:'overview',label:'概况'},{id:'entry',label:'参赛'},{id:'route',label:'赛道'},{id:'results',label:'成绩'},{id:'gallery',label:'图鉴'},{id:'updates',label:'动态'}];
const entryTypes=[{id:'registration',label:'报名中签'},{id:'guide',label:'参赛指南'}],galleryTypes=[{id:'参赛服',label:'参赛服',mark:'01'},{id:'奖牌',label:'奖牌',mark:'02'},{id:'参赛包',label:'参赛包',mark:'03'},{id:'完赛包',label:'完赛包',mark:'04'},{id:'albums',label:'官方图集',mark:'05'}];
const legacy={registration:'entry',logistics:'entry',participation:'results',gear:'gallery',stories:'updates'};
const normalized=value=>tabs.some(t=>t.id===value)?value:legacy[value]||'overview';
const tab=ref(normalized(route.query.tab)),gallery=ref(galleryTypes.some(g=>g.id===route.query.category)?String(route.query.category):'参赛服'),entryType=ref(route.query.tab==='logistics'||route.query.section==='guide'?'guide':'registration'),updatesType=ref(route.query.type==='news'?'news':'stories'),entryYear=ref(''),routeYear=ref(''),resultsYear=ref(''),galleryYear=ref(''),storyYear=ref('');let sequence=0;
const editions=computed(()=>[...(archive.value?.editions||[])].sort((a,b)=>Number(b.year)-Number(a.year))),years=computed(()=>editions.value.map(e=>String(e.year))),latest=computed(()=>editions.value[0]);
const foundingYear=computed(()=>archive.value?.profile?.foundingYear || '');
const history=computed(()=>archive.value?.history || []),visibleHistory=computed(()=>historyExpanded.value?history.value:history.value.slice(0,5));
const entryNotes=computed(()=>{const notes=archive.value?.profile?.entryNotes;return Array.isArray(notes)?notes:notes?[notes]:[];});
const sources=computed(()=>(archive.value?.sources||[]).map(source=>({...source,safeUrl:safeSourceUrl(source.url),yearsLabel:(source.applicableYears||[]).join('、')||'见对应事实'})));
const routeVersions=computed(()=>{const groups=archive.value?.routeGroups?.length?archive.value.routeGroups:(race.value?.id==='beijing'?[{id:'near-2025-2026',title:'2025—2026 · 奥体方向',years:['2026','2025'],match:'similar',note:'公开道路序列相近，各年细部线位分别记录。'}]:[]);const used=new Set();const result=groups.map(g=>({...g,years:(g.years||[]).map(String).filter(y=>years.value.includes(y))})).filter(g=>g.years.length).map(g=>{g.years.forEach(y=>used.add(y));return {...g,route:editions.value.find(e=>String(e.year)===g.years[0])?.route};});return [...result,...editions.value.filter(e=>!used.has(String(e.year))).map(e=>({id:String(e.year),title:e.route?.versionTitle||e.year+' 年路线',years:[String(e.year)],route:e.route}))];});
const activeRouteGroup=computed(()=>routeVersions.value.find(g=>g.years.includes(routeYear.value)));
const selected=y=>editions.value.find(e=>String(e.year)===y),currentEntry=computed(()=>selected(entryYear.value)),routeEdition=computed(()=>selected(routeYear.value)),resultEdition=computed(()=>selected(resultsYear.value));
const featuredResults=computed(()=>{
  const rows=resultEdition.value?.results||[];
  return ['男子','女子'].map(group=>rows.find(row=>new RegExp('^(?:(?:全程)?马拉松|全马)?(?:公开组)?'+group+'(?:公开组)?冠军$').test(row.group))).filter(Boolean);
});
const remainingResults=computed(()=>(resultEdition.value?.results||[]).filter(row=>!featuredResults.value.includes(row)));
const illustrationFailed=ref(false);
const hasHeroPhoto=computed(()=>Boolean(!heroFailed.value&&archive.value?.hero?.imageUrl));
const heroUrl=computed(()=>hasHeroPhoto.value?archive.value.hero.imageUrl:illustrationFailed.value?'':race.value?.id==='beijing'?import.meta.env.BASE_URL+'images/race-archive-art/beijing-cover.svg':landmarkUrl(race.value?.id));
const hasLandmark=computed(()=>Boolean(heroUrl.value&&!hasHeroPhoto.value&&race.value?.id!=='beijing'));
function heroImageError(){if(hasHeroPhoto.value)heroFailed.value=true;else illustrationFailed.value=true;}
const directoryTo=computed(()=>({path:'/race-catalog',query:Object.fromEntries(['q','wa','caa'].filter(k=>route.query[k]).map(k=>[k,route.query[k]]))})),fromRace=computed(()=>related.value.find(r=>String(r.id)===String(route.query.fromRaceId||'')));
const routeStages=computed(()=>String(routeEdition.value?.route?.summary||'').split('→').map(s=>s.trim()).filter(Boolean));
const registrationFields=[['fee','报名费用'],['qualification','报名资格'],['plannedQuota','计划名额'],['direct','直通规则'],['waitlist','候补规则'],['payment','缴费时间与方式'],['applicants','报名人数'],['eligibleApplicants','有效报名'],['lotteryPool','抽签池人数'],['drawQuota','抽签名额'],['lotteryRate','公布中签率'],['directQuota','直通名额']],participationFields=[['planned','计划规模'],['starters','实际起跑'],['finishers','完赛人数'],['finishRate','完赛率']];
const facts=(obj,fields)=>fields.filter(([key])=>obj?.[key]).map(([key,label])=>({label,value:obj[key]}));
const guideGroups=computed(()=>[{title:'领物安排',fields:facts(currentEntry.value?.logistics?.collection,[['time','领物时间'],['place','领物地点'],['requirements','领取要求']])},{title:'交通与离场',fields:facts(currentEntry.value?.logistics?.transport,[['expo','领物交通'],['start','前往起点'],['finish','终点离场']])},{title:'比赛日服务',fields:facts(currentEntry.value?.logistics?.raceDay,[['startTime','发枪与分区'],['timeLimit','关门安排'],['bagDrop','存取包'],['aidStations','补给与饮水'],['toilets','卫生间'],['medical','医疗服务']])}].filter(x=>x.fields.length));
function officialResources(edition,category){
  return (edition?.officialResources || []).filter(item=>category && item.category===category)
    .flatMap(item=>{const url=safeSourceUrl(item.url);return url?[{...item,url}]:[];});
}
function imageList(items,fallback,mediaRights){
  const images=(items || []).filter(item=>item.url);
  return fallback && !images.some(item=>item.url===fallback)?[{url:fallback,mediaRights},...images]:images;
}
function evidenceLinks(edition, category, facts) {
  const urls = new Map(officialResources(edition, category).map(link => [link.url, link]));
  for (const fact of facts.filter(Boolean)) for (const source of factSources(fact)) {
    if (source.applicableYears?.map(String).includes(String(edition?.year)) && !urls.has(source.safeUrl)) urls.set(source.safeUrl,{url:source.safeUrl,title:source.title});
  }
  return [...urls.values()];
}
const guideLinks=computed(()=>evidenceLinks(currentEntry.value,'guide',Object.values(currentEntry.value?.logistics||{})));
const resultLinks=computed(()=>evidenceLinks(resultEdition.value,'results',resultEdition.value?.results||[]));
const routeResources=computed(()=>officialResources(routeEdition.value,'route-map'));
const routeImages=computed(()=>{const r=routeEdition.value?.route;return imageList(r?.images,r?.mapUrl,r?.mediaRights);});
const galleryEntries=computed(()=>editions.value.filter(e=>!galleryYear.value||String(e.year)===galleryYear.value).map(e=>({
  year:e.year,
  items:(e.gear||[]).filter(g=>g.category===gallery.value).map(g=>({gear:g,images:imageList(g.images,g.imageUrl,g.mediaRights)})),
  resources:officialResources(e,{'参赛服':'shirt','奖牌':'medal'}[gallery.value])
})).filter(group=>group.items.length || group.resources.length));
const albums=computed(()=>[...(archive.value?.photoAlbums||[])].filter(e=>!galleryYear.value||String(e.year)===galleryYear.value).sort((a,b)=>Number(b.year)-Number(a.year))),stories=computed(()=>{const items=new Map();for(const item of [...(archive.value?.updates||[]),...(archive.value?.stories||[])])if(!items.has(item.title))items.set(item.title,item);return [...items.values()].filter(item=>!storyYear.value||String(item.editionYear)===storyYear.value);}),news=computed(()=>[...(archive.value?.news||[])].sort((a,b)=>String(b.publishedAt||'').localeCompare(String(a.publishedAt||''))));
function safeSourceUrl(value){try{const url=new URL(value);return ['https:','http:'].includes(url.protocol)&&!url.username&&!url.password?url.href:'';}catch{return '';}}
function factSources(item){return sources.value.filter(source=>source.safeUrl&&item.sourceIds?.includes(source.id));}
function statusLabel(value){return {completed:'已举办',scheduled:'已公告',cancelled:'已取消',postponed:'延期',upcoming:'待举办'}[value]||value;}
function certification(x){return x.label+(x.year?' · '+x.year:'');}function setTab(value){tab.value=value;}
function openEdition(year,id){
  const y=String(year);
  if(id==='route'){routeYear.value=y;setTab('route');}
  else if(id==='participation'){resultsYear.value=y;setTab('results');}
  else if(['shirt','medal'].includes(id)){galleryYear.value=y;gallery.value=id==='shirt'?'参赛服':'奖牌';setTab('gallery');}
  else if(id==='stories'){storyYear.value=y;updatesType.value='stories';setTab('updates');}
  else {entryYear.value=y;entryType.value=id==='logistics'?'guide':'registration';setTab('entry');}
