watch([tab,entryYear,routeYear,resultsYear,gallery,galleryYear,storyYear,entryType,updatesType],()=>{if(!archive.value||loading.value)return;const year=tab.value==='entry'?entryYear.value:tab.value==='route'?routeYear.value:tab.value==='results'?resultsYear.value:tab.value==='gallery'?galleryYear.value:tab.value==='updates'&&updatesType.value==='stories'?storyYear.value:'';router.replace({query:{...route.query,tab:tab.value,year:year||undefined,section:tab.value==='entry'?entryType.value:undefined,category:tab.value==='gallery'?gallery.value:undefined,type:tab.value==='updates'?updatesType.value:undefined}});},{flush:'post'});
